import{_ as t,o as a,c as o,a5 as s}from"./chunks/framework.Bqo7-qSd.js";const u=JSON.parse('{"title":"Upgrade to 2.9","description":"","frontmatter":{"title":"Upgrade to 2.9","order":4},"headers":[],"relativePath":"en/latest/tutorial/upgrade-2.9.md","filePath":"en/latest/tutorial/upgrade-2.9.md","lastUpdated":1795484315000}'),i={name:"en/latest/tutorial/upgrade-2.9.md"};function d(n,e,r,l,c,p){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="upgrade-to-2-9" tabindex="-1">Upgrade to 2.9 <a class="header-anchor" href="#upgrade-to-2-9" aria-label="Permalink to &quot;Upgrade to 2.9&quot;">​</a></h1><p>Konado 2.9 adds <code>call</code> / <code>return</code> subroutines and conditional / one-time choices (<code>choice ... if</code> / <code>once</code>), and <strong>drops compatibility with 2.8 saves and previously exported script data</strong>.</p><h2 id="incompatibilities" tabindex="-1">Incompatibilities <a class="header-anchor" href="#incompatibilities" aria-label="Permalink to &quot;Incompatibilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>2.8</th><th>2.9</th></tr></thead><tbody><tr><td>Compiler ABI</td><td><code>konado-2.8</code></td><td><code>konado-2.9</code></td></tr><tr><td>Command schema</td><td>3</td><td>4</td></tr><tr><td>Runtime state schema</td><td>2</td><td>3</td></tr></tbody></table><ul><li>2.8 <code>.kns</code> saves are rejected explicitly (&quot;存档格式与 Konado 2.9 不匹配&quot;) instead of loading with empty state.</li><li>Script data exported by 2.8 (encrypted <code>.res</code> or compiled data inside a PCK) no longer matches the ABI and must be re-exported.</li><li>2.9 ships no save-conversion tool; settle or migrate player progress inside a 2.8 build if you need it.</li></ul><h2 id="upgrade-steps" tabindex="-1">Upgrade steps <a class="header-anchor" href="#upgrade-steps" aria-label="Permalink to &quot;Upgrade steps&quot;">​</a></h2><ol><li>Replace the old plugin directories with the complete 2.9 set and reopen Godot so <code>.ks</code> files recompile.</li><li>Re-export the game; swapping the plugin inside an already shipped build is not supported.</li><li>Make sure every script that uses <code>choice</code> / <code>call</code> recompiles without diagnostics.</li></ol><h2 id="new-syntax-at-a-glance" tabindex="-1">New syntax at a glance <a class="header-anchor" href="#new-syntax-at-a-glance" aria-label="Permalink to &quot;New syntax at a glance&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>call common_scene</span></span>
<span class="line"><span>return</span></span>
<span class="line"><span></span></span>
<span class="line"><span>choice &quot;Option&quot; -&gt; branch_name if %love &gt;= 5</span></span>
<span class="line"><span>choice &quot;Ask once&quot; -&gt; branch_name once</span></span></code></pre></div><p>See &quot;Subroutine Calls (call / return)&quot; and &quot;Choice&quot; for details.</p>`,10)])])}const m=t(i,[["render",d]]);export{u as __pageData,m as default};
